236	/**
237	 * Update an existing status table in-place by replacing badge contents and
238	 * branch text for each repository whose status has changed.
239	 *
240	 * Rows are located via `[data-repo-id]` on both the `<tr>` and the badge
241	 * wrapper `<div>` inside it. No full re-render of the table is performed.
242	 *
243	 * @param {HTMLElement}           tableBody - The `<tbody>` to update.
244	 * @param {Record<string, Object|null>} statusMap - Keyed by repository ID.
245	 */
246	function updateStatusTable(tableBody, statusMap) {
247	    for (const [repoId, statusInfo] of Object.entries(statusMap)) {
248	        const row = tableBody.querySelector(`tr[data-repo-id="${CSS.escape(repoId)}"]`);
249	        if (!row) continue;

250	
251	        // Update branch cell (second cell)
252	        const branchCell = row.cells[1];
253	        if (branchCell) {
254	            branchCell.textContent = (statusInfo && statusInfo.currentBranch)
255	                ? statusInfo.currentBranch
256	                : '—';
257	        }
258	
259	        // Update badge wrapper (third cell → div[data-repo-id])
260	        const badgeWrapper = row.querySelector(`div[data-repo-id="${CSS.escape(repoId)}"]`);
261	        if (badgeWrapper) {
262	            badgeWrapper.innerHTML = '';
263	            badgeWrapper.appendChild(createStatusBadge(statusInfo || null));
264	        }
265	    }
266	}
