384	/**
385	 * Create the "Open in VS Code" button and wire its click handler.
386	 *
387	 * The button calls `api.workspaces.openVscode` and shows a success or error
388	 * toast based on the API response. It is only rendered when the workspace is
389	 * initialised (`workspace.initialized === true`).
390	 *
391	 * @param {string} projectId
392	 * @param {string} workspaceId
393	 * @returns {HTMLButtonElement}
394	 */
395	function createOpenVscodeButton(projectId, workspaceId) {
396	    const btn = document.createElement('button');
397	    btn.type      = 'button';
398	    btn.className = 'btn btn-secondary btn-sm';
399	    btn.textContent = 'Open in VS Code';

396	    const btn = document.createElement('button');
397	    btn.type      = 'button';
398	    btn.className = 'btn btn-secondary btn-sm';
399	    btn.textContent = 'Open in VS Code';
400	    btn.title = 'Open this workspace folder in Visual Studio Code.';
401	
402	    btn.addEventListener('click', async () => {
403	        btn.disabled = true;
404	        btn.textContent = 'Opening…';
405	
406	        try {
407	            await api.workspaces.openVscode(projectId, workspaceId);
408	            showToast('VS Code launched for this workspace.', 'success');
409	        } catch (err) {
410	            showToast(err.message || 'Failed to open VS Code.', 'error');
411	        } finally {
412	            btn.disabled = false;
413	            btn.textContent = 'Open in VS Code';
414	        }
415	    });
416	
417	    return btn;
418	}
