420	/**
421	 * Build the workspace header section — compact layout with breadcrumb,
422	 * workspace name, and a meta card for description + management actions.
423	 *
424	 * @param {string} projectId
425	 * @param {{ id: string, description: string, initialized: boolean, folderPath: string }} workspace
426	 * @param {boolean} isStable
427	 * @param {function(): void} [onSetupSuccess] - Called after a successful setup to trigger refresh.
428	 * @returns {HTMLElement}
429	 */
430	function buildHeaderSection(projectId, workspace, isStable, onSetupSuccess) {
431	    const wrapper = document.createElement('div');
432	    wrapper.className = 'workspace-detail-header';
433	
434	    // Breadcrumb
435	    const breadcrumb = document.createElement('nav');
436	    breadcrumb.className = 'breadcrumb back-link text-muted';
437	    breadcrumb.setAttribute('aria-label', 'Breadcrumb');
438	
439	    const projectLink = document.createElement('a');
440	    projectLink.href      = `#/projects/${encodeURIComponent(projectId)}`;
441	    projectLink.textContent = `← ${projectId}`;
442	    projectLink.className = 'breadcrumb-link';
443	    if (_router) {
444	        projectLink.addEventListener('click', (e) => {
445	            e.preventDefault();
446	            _router.navigate(`#/projects/${encodeURIComponent(projectId)}`);
447	        });
448	    }
449	    breadcrumb.appendChild(projectLink);
450	    wrapper.appendChild(breadcrumb);
451	
452	    // Title row: workspace ID
453	    const titleRow = document.createElement('div');
454	    titleRow.className = 'workspace-meta-top-row';
455	
456	    const titleEl = document.createElement('h1');
457	    titleEl.className   = 'project-meta-name';
458	    titleEl.textContent = workspace.id;
459	    titleRow.appendChild(titleEl);
460	
461	    // Description (inline, muted)
462	    if (workspace.description) {
463	        const descEl = document.createElement('span');
464	        descEl.className   = 'project-meta-id text-muted';
465	        descEl.textContent = workspace.description;
466	        titleRow.appendChild(descEl);
467	    }
468	
469	    wrapper.appendChild(titleRow);
470	
471	    // Folder path row (shown when path is available)
472	    if (workspace.folderPath) {
473	        const pathRow = document.createElement('div');
474	        pathRow.className = 'workspace-folder-path-row';
475	
476	        const pathLabel = document.createElement('span');
477	        pathLabel.className = 'text-muted';
478	        pathLabel.textContent = 'Path: ';
479	
480	        const pathValue = document.createElement('code');
481	        pathValue.className = 'workspace-folder-path font-mono';
482	        pathValue.textContent = workspace.folderPath;
483	
484	        pathRow.appendChild(pathLabel);
485	        pathRow.appendChild(pathValue);
486	        wrapper.appendChild(pathRow);
487	    }
488	
489	    // Management row: rename, delete, setup
490	    const mgmtRow = document.createElement('div');
491	    mgmtRow.className = 'workspace-mgmt-row';
492	
493	    // Setup button (if not initialized)
494	    if (!workspace.initialized) {
495	        const setupBtn = document.createElement('button');
496	        setupBtn.type      = 'button';
497	        setupBtn.className = 'btn btn-primary btn-sm';
498	        setupBtn.textContent = 'Setup Workspace';
499	        setupBtn.title = 'Initialize workspace on disk (create folder, clone repos).';
500	
501	        setupBtn.addEventListener('click', async () => {
502	            setupBtn.disabled = true;
503	            setupBtn.textContent = 'Setting up…';
504	
505	            try {
506	                await runSetup(projectId, workspace.id,
507	                    `Workspace "${workspace.id}" set up successfully.`);
508	
509	                // Update DOM in-place — remove setup button, insert "Open in VS Code",
510	                // update state flag, and notify caller.
511	                setupBtn.remove();
512	                workspace.initialized = true;
513	                const vscodeBtn = createOpenVscodeButton(projectId, workspace.id);
514	                mgmtRow.insertBefore(vscodeBtn, renameBtn);
515	                if (onSetupSuccess) onSetupSuccess();
516	            } catch (err) {
517	                showToast(err.message || 'Failed to set up workspace.', 'error');
518	                setupBtn.disabled = false;
519	                setupBtn.textContent = 'Setup Workspace';
520	            }
521	        });
522	        mgmtRow.appendChild(setupBtn);
523	    }
524	
525	    // "Open in VS Code" button — shown only when the workspace is initialized
526	    if (workspace.initialized) {
527	        mgmtRow.appendChild(createOpenVscodeButton(projectId, workspace.id));
528	    }
529	
530	    // Rename button (disabled for STABLE)
531	    const renameBtn = document.createElement('button');
532	    renameBtn.type      = 'button';
533	    renameBtn.className = 'btn btn-secondary btn-sm';
534	    renameBtn.textContent = 'Rename';
