592	/**
593	 * Build the repository status table section.
594	 *
595	 * @param {Array<{ repoId: string, repoName: string }>} repos
596	 * @param {Record<string, Object|null>} statusMap
597	 * @param {string} projectId - Project ID, threaded to each row's "Open" button.
598	 * @param {string} wid - Workspace ID, threaded to each row's "Open" button.
599	 * @returns {{ section: HTMLElement, tbody: HTMLTableSectionElement }}
600	 */
601	function buildStatusTableSection(repos, statusMap, projectId, wid) {
602	    const section = document.createElement('section');
603	    section.className = 'workspace-status-section';
604	
605	    if (repos.length === 0) {
606	        const empty = document.createElement('p');
607	        empty.className   = 'empty-state-inline text-secondary';
608	        empty.textContent = 'No repositories in this project.';
609	        section.appendChild(empty);
610	        return { section, tbody: null };
611	    }
612	
613	    const table = document.createElement('table');
614	    table.className = 'data-table workspace-status-table';
615	
